// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        bool ok = true;
        vm.prank(actor);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: only the contract deployer (owner) may call NETM();
        // any other caller's call must revert.
        assertTrue(!ok);
    }
}
